package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Random;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class RandomStringUtils_random_TriageGen2Test {

    @Test
    public void testRandom_CountZero() {
        String result = RandomStringUtils.random(0, 0, 0, false, false, null, new Random());
        assertEquals("", result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testRandom_CountNegative() {
        RandomStringUtils.random(-1, 0, 0, false, false, null, new Random());
    }

    @Test
    public void testRandom_DefaultRangeNoLettersNoNumbers() {
        // start=0, end=0, letters=false, numbers=false -> end becomes Integer.MAX_VALUE
        // This tests the branch: if (start == 0 && end == 0) { if (!letters && !numbers) { end = Integer.MAX_VALUE; } }
        String result = RandomStringUtils.random(5, 0, 0, false, false, null, new Random());
        assertEquals(5, result.length());
    }

    @Test
    public void testRandom_DefaultRangeWithLettersOrNumbers() {
        // start=0, end=0, letters=true -> end becomes 'z'+1, start becomes ' '
        String result = RandomStringUtils.random(5, 0, 0, true, false, null, new Random());
        assertEquals(5, result.length());
    }

    @Test
    public void testRandom_UsingCharsArray() {
        char[] allowed = {'A', 'B', 'C'};
        // gap = 3 - 0 = 3. random.nextInt(3) + 0 -> 0, 1, or 2
        String result = RandomStringUtils.random(5, 0, 3, false, false, allowed, new Random());
        assertEquals(5, result.length());
        for (char c : result.toCharArray()) {
            assertTrue(c == 'A' || c == 'B' || c == 'C');
        }
    }

    @Test
    public void testRandom_FilterLogic() {
        // Test filtering: only numbers allowed, but range contains letters
        // We use a custom Random to control the sequence if needed, but here we just check constraints
        char[] mixed = {'a', '1', 'B', '2'};
        // start=0, end=4, letters=false, numbers=true
        String result = RandomStringUtils.random(10, 0, 4, false, true, mixed, new Random());
        assertEquals(10, result.length());
        for (char c : result.toCharArray()) {
            assertTrue(Character.isDigit(c));
        }
    }

    @Test
    public void testRandom_SurrogatePairs_LowSurrogate() {
        // Low surrogate: 56320 to 57343
        // We force the random to pick a low surrogate
        Random mockedRandom = new Random() {
            private int count = 0;
            @Override
            public int nextInt(int bound) {
                if (count++ == 0) return 56320 - 0; // Force low surrogate
                return 0;
            }
        };
        // Use chars to avoid the complex start/end logic and force the specific char
        char[] lowSurrogate = {(char) 56320}; 
        // Note: the code does: ch = chars[random.nextInt(gap) + start]
        // To trigger the low surrogate branch:
        String result = RandomStringUtils.random(1, 0, 1, false, false, lowSurrogate, mockedRandom);
        // Since count becomes 0 in the loop, it checks if(count == 0) and increments it to prevent buffer overflow
        // but the logic 'if(count==0) count++' in the low surrogate branch is a bit strange in the source.
        // Let's test a count > 1 to hit the buffer[count] = ch; count--; buffer[count] = ... logic.

        Random mockedRandom2 = new Random() {
            private int call = 0;
            @Override
            public int nextInt(int bound) {
                if (call == 0) { call++; return 0; } // Pick low surrogate
                if (call == 1) { call++; return 0; } // Pick high surrogate for the fallback
                return 0;
            }
        };
        char[] low = {(char) 56320};
        String result2 = RandomStringUtils.random(2, 0, 1, false, false, low, mockedRandom2);
        // result2 should contain the low surrogate + a high surrogate
        assertTrue(result2.length() >= 1);
    }

    @Test
    public void testRandom_SurrogatePairs_HighSurrogate() {
        // High surrogate: 55296 to 56191
        Random mockedRandom = new Random() {
            private int call = 0;
            @Override
            public int nextInt(int bound) {
                if (call == 0) { call++; return 55296 - 0; } 
                return 0;
            }
        };
        char[] high = {(char) 55296};
        String result = RandomStringUtils.random(2, 0, 1, false, false, high, mockedRandom);
        assertTrue(result.length() >= 1);
    }

    @Test
    public void testRandom_PrivateSurrogate_Skip() {
        // Private high surrogate: 56192 to 56319
        char[] privateSurrogate = {(char) 56200};
        // This should trigger the count++ (skip) branch
        String result = RandomStringUtils.random(5, 0, 1, false, false, privateSurrogate, new Random());
        // Since it skips, it should eventually return an empty string if it keeps picking it, 
        // or a string of length 5 if it picks others.
        // To ensure coverage, we just call it.
        assertNotNull(result);
    }

    @Test
    public void testRandom_ComplexBranchCoverage() {
        // This test aims to hit the combination of letters=true, numbers=true
        char[] all = {'a', '1', '!', '@'};
        String result = RandomStringUtils.random(10, 0, 4, true, true, all, new Random());
        assertNotNull(result);
    }
}
